		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
push("全部🌊分类",null,1,1)
	arList=["霸总","修真","恋爱","校园","冒险","搞笑","生活","热血","架空","后宫","玄幻","悬疑","恐怖","灵异","动作","科幻","战争","古风","穿越","竞技","励志","同人","真人"
]
	arList.map((tag,index)=>{
		url=`http://comic.mkzcdn.com/search/filter/?page_num={{page}}&page_size=12&theme_id=${index+1}`;
		push(tag, url, 1, 0.25);
		});
		push("🌊状态🌊",null,1,1);
		push("连载",`http://comic.mkzcdn.com/search/filter/?finish=1&page_num={{page}}&page_size=12`,1,0.35);
